def visual_token_budget(n_seg, n_abs, n_patch, rho=0.0):
    # n_seg 段，每段 n_abs 个抽象 token；rho 为额外暴露的 patch token 比例
    return n_seg * n_abs + round(rho * n_seg * n_patch)

