import numpy as np

def rank_actions(model, state, actions, H=5, gamma=0.99):
    """用 H 步想象轨迹的折扣回报给候选动作排序。"""
    scores = []
    for a in actions:
        s, total = state, 0.0
        for k in range(H):
            s, r = model.step(s, a)      # 世界模型前向一步
            total += (gamma ** k) * r
        scores.append(total)             # 目标超出行程时各动作分数几乎相同
    return np.argsort(-np.asarray(scores)), np.asarray(scores)

def looped_deep_supervision(loss_fn, outs_per_loop, targets, weights=None):
    # outs_per_loop: 每个循环的输出, len == K
    k = len(outs_per_loop)
    if weights is None:
        weights = [1.0 / k] * k            # 默认等权；原文配比未给出
    total = 0.0
    for w, out in zip(weights, outs_per_loop):
        total = total + w * loss_fn(out, targets)
    return total                            # 循环间深监督：每个循环都拿梯度

import torch


def wush_transforms(X, W, eps=1e-5):
    """示意：分别用两个因子的二阶统计做白化，成对施加以保持乘积不变。"""
    def whiten(S):
        d, V = torch.linalg.eigh(S + eps * torch.eye(S.shape[0], device=S.device))
        return V @ torch.diag(d.rsqrt()) @ V.t()

    Sx = X.t() @ X / max(X.shape[0] - 1, 1)      # [d_in, d_in]
    Sw = W @ W.t() / max(W.shape[1] - 1, 1)      # [d_out, d_out]
    Tx, Tw = whiten(Sx), whiten(Sw)
    # X @ W == (Tx @ X) @ (Tw.inverse() @ W)  -> 成对量化后再还原
    return Tx, torch.linalg.inv(Tw)

def success_rate(results, human=0.834):
