import networkx as nx


def structure_credit(graph, root, total_score, gamma=0.7):
    """按工作流 DAG 的拓扑距离，把单一稀疏总分摊给各角色。"""
    dist = nx.single_source_shortest_path_length(graph, root)
    phi = {v: gamma ** d for v, d in dist.items()}
    z = sum(phi.values())
    return {v: total_score * w / z for v, w in phi.items()}

import numpy as np  # ECE：按置信度分 M 个桶

def ece(probs, labels, M=10):
    conf = probs.max(1); pred = probs.argmax(1)
    bins = np.linspace(0, 1, M + 1)
    e = 0.0
    for lo, hi in zip(bins[:-1], bins[1:]):
        m = (conf > lo) & (conf <= hi)              # 第 m 个桶
        if m.sum():
            e += m.mean() * abs((pred[m] == labels[m]).mean() - conf[m].mean())
    return e

