def quick_sort_hoare(nums):
    """另一种写得出彩的版本：Hoare 划分 + 三数取中。面试里说清楚「为什么比 Lomuto 少交换」。"""
    def median3(lo, hi):
        mid = (lo + hi) // 2
        a, b, c = nums[lo], nums[mid], nums[hi]
        if a > b:
            lo, mid = mid, lo
        if nums[lo] > nums[hi]:
            lo, hi = hi, lo
        if nums[mid] > nums[hi]:
            mid, hi = hi, mid
        return nums[mid]

    def partition(lo, hi):
        pivot = median3(lo, hi)
        i, j = lo - 1, hi + 1
        while True:
            i += 1
            while nums[i] < pivot:
                i += 1
            j -= 1
            while nums[j] > pivot:
                j -= 1
            if i >= j:
                return j
            nums[i], nums[j] = nums[j], nums[i]

    def sort(lo, hi):
        if lo >= hi:
            return
        p = partition(lo, hi)
        sort(lo, p)
        sort(p + 1, hi)

    sort(0, len(nums) - 1)
    return nums

