def longestOnes(nums, k):
    # 只关心 0：把 0 的下标看成考场座位，窗口最多容纳 k 个 0
    zeros_pos = [i for i, x in enumerate(nums) if x == 0]
    if len(zeros_pos) <= k:
        return len(nums)
    best = 0
    left = 0
    for right in range(len(zeros_pos)):
        while right - left + 1 > k:
            left += 1
        # 两个端点之间（含外侧 1）构成合法窗口
        lo = 0 if left == 0 else zeros_pos[left - 1] + 1
        hi = len(nums) - 1 if right == len(zeros_pos) - 1 else zeros_pos[right + 1] - 1
        best = max(best, hi - lo + 1)
    return best


