    def serialize(self, root) -> str:
        if root is None:
            return ''
        q, out = deque([root]), []
        while q:
            node = q.popleft()
            if node is None:
                out.append('#')
            else:
                out.append(str(node.val))
                q.append(node.left)
                q.append(node.right)
