def min_transport_cost(n, edges, start=1, end=None):
    """edges: [[s, t, w], ...]，权值可为负；无负权环。
    返回 start 到 end 的最小成本，不可达返回 None。"""
    if end is None:
        end = n
    INF = float('inf')
    dist = [INF] * (n + 1)
    dist[start] = 0
    for _ in range(n - 1):
        updated = False
        for s, t, w in edges:
            if dist[s] != INF and dist[s] + w < dist[t]:
                dist[t] = dist[s] + w
                updated = True
        if not updated:
