def largest_sum_after_k_negations(nums, k):
    """返回恰好执行 k 次取反后数组可能的最大和。"""
    nums.sort(key=abs, reverse=True)      # 按绝对值降序，优先处理大绝对值
    for i in range(len(nums)):
        if nums[i] < 0 and k > 0:
            nums[i] = -nums[i]
            k -= 1
    if k % 2 == 1:                        # 剩余奇数次：翻绝对值最小的
