def restoreIpAddresses(s: str) -> list:
    res, n = [], len(s)

    def dfs(start: int, seg: int, path: list):
        if seg == 4:
            if start == n:
                res.append(".".join(path))
            return
        # 剪枝：剩余字符必须能填满剩余段，又不能超过每段 3 位
