                break
            part = s[start:start + length]
            if len(part) > 1 and part[0] == '0':
                break          # 前导零，且更长候选必然也非法
            if int(part) > 255:
                break          # 数值越界，更长只会更大
            path.append(part)
            dfs(start + length, seg + 1, path)
            path.pop()

    dfs(0, 0, [])
    return res

