def mmd2(feats_p, feats_q, sigma=1.0):
    # feats_p/feats_q: [N, D] / [M, D] 两组特征（含逐 token 观测）
    def k(a, b):
        d2 = ((a[:, None, :] - b[None, :, :]) ** 2).sum(-1)
