def ducb_select(loss_ema, eff_n, t):
    """折扣 UCB：上界 = EMA 损失 + 基于折扣有效样本量的置信半径。"""
    ucb = loss_ema + np.sqrt(2.0 * np.log(t + 1) / np.maximum(eff_n, 1.0))
    return int(np.argmax(ucb))


def ducb_update(loss_ema, eff_n, k, loss_k, gamma=0.99):
    loss_ema[k] = gamma * loss_ema[k] + (1 - gamma) * loss_k  # 指数滑动平均
    eff_n[k] = gamma * eff_n[k] + 1.0                          # 折扣有效样本量
    return loss_ema, eff_n

