import torch
def plan(actions, z0, f, g, target, steps=200, lr=0.05):
    a = actions.clone().requires_grad_(True)
    opt = torch.optim.Adam([a], lr=lr)
    for _ in range(steps):
        z, loss = z0, 0.0
        for t in range(a.size(0)):
            z = f(z, a[t])
            loss = loss + ((g(z) - target[t]) ** 2).sum()
        opt.zero_grad(); loss.backward(); opt.step()
    return a.detach()

def textreg_step(prompt, task_loss, omega, lam, textual_grad, keep=3):
