    loss = task_loss + lam * omega
    # 文本梯度由 LLM 反馈给出，先净化掉只支持单个样本的方向
    purified = [g['edit'] for g in textual_grad if g.get('support', 1) > 1]
    return loss, prompt + '\n' + '\n'.join(purified[:keep])

